KB = '"Kuriboh"'
MW = '"Magnet Warrior"'
MA = '"Magna Warrior"'
HP = '"Harpie"'
ALW = '(Esta carta siempre se trata como una carta ' + KB + '.)\n'
FIVE = '(1 "Kuribah", 1 "Kuribee", 1 "Kuriboo", 1 "Kuribeh" y 1 "Kuriboh")'
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def eachf(n): return ' Sólo puedes usar cada uno de los siguientes efectos de "%s" una vez por turno.' % n
def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def electro(n, first): return 'Si esta carta es Invocada de Modo Normal o Especial: ' + first + once(n) + ' Durante el turno de tu adversario: puedes Sacrificar esta carta; Invoca de Modo Especial 1 monstruo ' + MW + ' de Nivel 4 de tu Deck (éste es un Efecto Rápido).'
ES = {
"Conduction Warrior Plasma Magnum": '2 monstruos de TIERRA de Tipo Roca\nLos monstruos boca arriba en el Campo pasan a ser de TIERRA.' + eachf("Conduction Warrior Plasma Magnum") + ' Si esta carta es Invocada por Fusión: puedes añadir a tu mano 1 Mágica Normal, Rápida o de Campo "Magnet" de tu Deck. Puedes mandar al Cementerio 1 monstruo ' + MA + ' de Nivel 8 de tu Deck; inmediatamente después de que este efecto se resuelva, Invoca de Modo Normal 1 monstruo ' + MW + ' de Nivel 4 o menor.',
"Ankuriboh": 'Cuando un monstruo de tu adversario declare un ataque: puedes descartar esta carta y, después, seleccionar 1 monstruo en cualquier Cementerio, excepto esta carta; Invócalo de Modo Especial a tu Campo, pero mándalo al Cementerio durante la End Phase. Si esta carta es destruida en batalla o por un efecto de carta y mandada al Cementerio: puedes añadir a tu mano 1 "Monster Reborn" de tu Deck o Cementerio durante la End Phase de este turno.' + each("Ankuriboh"),
"Astral Kuriboh": 'Puedes mostrar 1 Monstruo Xyz "Number" de tu Extra Deck; Invoca esta carta de Modo Especial desde tu mano. Si lo haces, el Nivel de esta carta pasa a ser el Rango del monstruo mostrado y, además, mientras esté boca arriba en la Zona de Monstruos, no puedes Invocar de Modo Especial monstruos desde el Extra Deck, excepto Monstruos Xyz "Number".' + once("Astral Kuriboh") + ' Un Monstruo Xyz "Number" que fue Invocado usando como material esta carta en el Campo obtiene este efecto.\n● No puede ser destruido en batalla ni por efectos de cartas de tu adversario.',
"Clear Kuriboh": 'Cuando tu adversario active un efecto de monstruo que fuera a infligir daño (Efecto Rápido): puedes descartar esta carta; niega la activación. Cuando un monstruo de tu adversario declare un ataque directo: puedes desterrar esta carta de tu Cementerio; roba 1 carta y, si es un monstruo, puedes Invocarlo de Modo Especial y, después, cambiar el objetivo del ataque a él.' + once("Clear Kuriboh"),
"Darkuriboh": 'Cuando uno o más monstruos de Tipo Demonio y/o Monstruos de Fusión que controlas sean elegidos como objetivo de un ataque, o se active una carta o efecto que los seleccione (Efecto Rápido): puedes descartar esta carta y, después, seleccionar 1 de esos monstruos; hasta el final de este turno, no puede ser destruido en batalla ni por efectos de cartas y, además, sus efectos activados en la Zona de Monstruos no pueden ser negados. Si esta carta es mandada de la mano al Cementerio por un efecto de carta: puedes añadir a tu mano 1 "Polymerization" de tu Deck o Cementerio.' + each("Darkuriboh"),
"Detonating Kuriboh": 'Si hay una Carta de Monstruo ' + KB + ' en el Campo: puedes Invocar esta carta de Modo Especial desde tu mano. Cuando tu adversario active un efecto de monstruo en el Campo (Efecto Rápido): puedes equipar esta carta que controlas a ese monstruo de tu adversario como una Mágica de Equipo con el siguiente efecto.\n● Los efectos del monstruo equipado quedan negados.\nSólo puedes usar cada efecto de "Detonating Kuriboh" una vez por turno.',
"Galactikuriboh": '(Esta carta siempre se trata como una carta "Galaxy".)\nCuando un monstruo de tu adversario declare un ataque: puedes descartar esta carta; Invoca de Modo Especial 1 "Galaxy-Eyes Photon Dragon" de tu mano o Deck, después cambia el objetivo del ataque a él y, después, puedes acoplar esta carta desde el Cementerio a 1 Monstruo Xyz en el Campo como material. Si uno o más monstruos "Photon" o "Galaxy" que controlas fueran a ser destruidos en batalla o por un efecto de carta de tu adversario, puedes desterrar esta carta de tu Cementerio en su lugar.',
"Junkuriboh": 'Cuando tu adversario active una carta o efecto que te fuera a infligir daño (Efecto Rápido): puedes mandar esta carta de tu mano o Campo al Cementerio; niega la activación y, si lo haces, destruye esa carta.',
"Kuribah": ALW + 'Cuando esta carta, u otro monstruo ' + KB + ' que controles, sea destruido en batalla: puedes Invocar de Modo Especial 1 monstruo con 300 ATK/200 DEF de tu Deck, excepto "Kuribah".' + once("Kuribah") + ' Puedes Sacrificar esta carta que controlas y 1 de cada uno de "Kuribee", "Kuriboo", "Kuribeh" y "Kuriboh" de tu mano y/o Campo; Invoca de Modo Especial 1 "Kuribabylon" de tu mano, Deck o Cementerio.',
"Kuribee": ALW + 'Cuando esta carta, u otro monstruo ' + KB + ' que controles, sea destruido en batalla: puedes añadir a tu mano, desde tu Deck, 1 Mágica/Trampa que mencione la carta "Kuriboh" en su texto.' + once("Kuribee") + ' Una vez por turno, cuando un monstruo de tu adversario declare un ataque mientras controlas otro monstruo ' + KB + ': puedes cambiar a 0 el ATK de todos los demás monstruos que controlas hasta el final de este turno y, si lo haces, niega el ataque.',
"Kuribeh": ALW + '(Efecto Rápido): Puedes descartar esta carta y, después, seleccionar 1 monstruo ' + KB + ' que controles; gana 1500 ATK. Puedes Sacrificar esta carta que controlas y 1 de cada uno de "Kuribah", "Kuribee", "Kuriboo" y "Kuriboh" de tu mano y/o Campo; añade a tu mano 1 "Kuribandit" de tu Deck o Cementerio y, después, inmediatamente después de que este efecto se resuelva, puedes Invocar de Modo Normal 1 monstruo de Tipo Demonio de tu mano.',
"Kuribohrn": 'Al final de la Battle Phase: puedes descartar esta carta y, después, seleccionar 1 monstruo en tu Cementerio que fue destruido en batalla y mandado allí este turno; Invócalo de Modo Especial. Cuando un monstruo de tu adversario declare un ataque: puedes desterrar esta carta de tu Cementerio y, después, seleccionar cualquier número de monstruos ' + KB + ' en tu Cementerio; Invócalos de Modo Especial.',
"Kuriboo": ALW + 'Cuando un monstruo de tu adversario declare un ataque: puedes descartar esta carta; añade a tu mano 1 monstruo ' + KB + ' de tu Deck, excepto "Kuriboo". Una vez por turno (Efecto Rápido): puedes descartar 1 Trampa y, después, seleccionar 1 monstruo boca arriba que controle tu adversario; pierde 1500 ATK hasta el final de este turno.',
"Multiplying Kuriboh!": 'Cuando tu adversario active un efecto de monstruo, o un monstruo de tu adversario declare un ataque (Efecto Rápido): puedes Invocar esta carta de Modo Especial desde tu mano.' + once("Multiplying Kuriboh!") + ' Una vez por turno, cuando tu adversario active un efecto de monstruo en el Campo, o durante el cálculo de daño, cuando un monstruo de tu adversario ataque (Efecto Rápido): puedes añadir a tu mano, o Invocar de Modo Especial, 1 "Dark Magician" o 1 monstruo con 300 ATK/200 DEF de tu Deck o Cementerio y, después, puedes cambiar a 0 el ATK de ese monstruo de tu adversario.',
"Performapal Kuribohble": 'Cuando un monstruo de tu adversario declare un ataque directo: puedes Invocar esta carta de Modo Especial desde tu mano y, si lo haces, cambia el objetivo del ataque a esta carta y procede al cálculo de daño. Si fueras a recibir daño de batalla de esa batalla, en su lugar ganas esa cantidad de LP.',
"Rainbow Kuriboh": 'Sólo puedes usar cada efecto de "Rainbow Kuriboh" una vez por turno.\n● Cuando un monstruo de tu adversario declare un ataque: puedes seleccionar ese monstruo atacante; equipa esta carta desde tu mano a ese monstruo. No puede atacar.\n● Cuando un monstruo de tu adversario declare un ataque directo mientras esta carta está en tu Cementerio: puedes Invocar esta carta de Modo Especial, pero destiérrala cuando deje el Campo.',
"Relinkuriboh": 'Si esta carta es Sacrificada: roba 1 carta. Si tu monstruo fuera a ser destruido en batalla, puedes desterrar esta carta de tu Cementerio en su lugar.',
"Sphere Kuriboh": 'Cuando un monstruo de tu adversario declare un ataque: puedes mandar esta carta de tu mano al Cementerio; cambia el monstruo atacante a Posición de Defensa. Cuando hagas una Invocación por Ritual, puedes desterrar esta carta de tu Cementerio como 1 de los monstruos requeridos para la Invocación por Ritual.',
"Winged Kuriboh Sabatiel LV10": 'Puedes mostrar esta carta de tu mano y pagar la mitad de tus LP; añade a tu mano 1 Mágica "Polymerization" o "Fusion" de tu Deck y, si lo haces, baraja esta carta en el Deck y, además, no puedes Invocar de Modo Especial desde el Extra Deck durante el resto de este turno, excepto monstruos "HERO". Durante el turno de tu adversario, si tus LP son 1000 o menos (Efecto Rápido): puedes Invocar esta carta de Modo Especial desde tu mano y, después, puedes infligir a tu adversario daño igual al ATK más alto entre los monstruos que controla (a tu elección, si hay empate).' + each("Winged Kuriboh Sabatiel LV10"),
"Alpha The Electromagnet Warrior": electro("Alpha The Electromagnet Warrior", 'puedes añadir a tu mano 1 monstruo ' + MA + ' de Nivel 8 de tu Deck.'),
"Beta The Electromagnet Warrior": electro("Beta The Electromagnet Warrior", 'puedes añadir a tu mano 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Deck, excepto "Beta The Electromagnet Warrior".'),
"Gamma The Electromagnet Warrior": electro("Gamma The Electromagnet Warrior", 'puedes Invocar de Modo Especial 1 monstruo ' + MW + ' de Nivel 4 o menor de tu mano, excepto "Gamma The Electromagnet Warrior".'),
"Kuribandit": 'Durante la End Phase, si esta carta fue Invocada de Modo Normal este turno: puedes Sacrificar esta carta; excava las 5 cartas superiores de tu Deck, puedes añadir a tu mano 1 Mágica/Trampa excavada y, además, manda al Cementerio el resto de las cartas.',
"Delta The Magnet Warrior": 'Si esta carta es Invocada de Modo Normal o Especial: puedes mandar al Cementerio 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Deck. Si esta carta es mandada al Cementerio: puedes desterrar 3 monstruos ' + MW + ' de Nivel 4 o menor de tu Cementerio, excepto "Delta The Magnet Warrior"; Invoca de Modo Especial 1 "Valkyrion the Magna Warrior" de tu mano o Deck, ignorando sus condiciones de Invocación.' + each("Delta The Magnet Warrior"),
"Epsilon The Magnet Warrior": 'Si esta carta es Invocada de Modo Normal o Especial: puedes mandar al Cementerio 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Deck, excepto "Epsilon The Magnet Warrior"; el nombre de esta carta pasa a ser el del monstruo mandado (hasta la End Phase) y, después, puedes Invocar de Modo Especial 1 monstruo ' + MW + ' o ' + MA + ' de tu Cementerio con un nombre distinto al de las cartas que controlas.' + once("Epsilon The Magnet Warrior"),
"Magnet Warrior Omega Plus": 'Si esta carta está en tu mano o Cementerio: puedes destruir 1 otro monstruo de Tipo Roca de tu mano o Campo boca arriba y, si lo haces, Invoca esta carta de Modo Especial, pero destiérrala cuando deje el Campo. Cuando se active el efecto de un monstruo de TIERRA en el Campo (Efecto Rápido): puedes Sacrificar esta carta y, después, seleccionar 1 monstruo boca arriba en el Campo; cámbialo a Posición de Defensa boca abajo.' + each("Magnet Warrior Omega Plus"),
"Magnet Warrior Sigma Minus": 'Una vez por turno, cuando se declare un ataque que involucre a 2 monstruos de TIERRA: puedes negar ese ataque.' + eachf("Magnet Warrior Sigma Minus") + ' Puedes mostrar esta carta de tu mano; Invoca por Fusión 1 Monstruo de Fusión de tu Extra Deck, usando monstruos de Tipo Roca de tu mano o Campo, incluyendo esta carta de tu mano. Si esta carta es Invocada de Modo Normal o Especial: puedes mandar al Cementerio 1 monstruo ' + MA + ' de Nivel 8 de tu Deck.',
"Magnet Warrior Sigma Plus": 'Mientras controles un monstruo de TIERRA, los monstruos de tu adversario que puedan atacar deben atacar a monstruos de TIERRA. Mientras tu adversario controle un monstruo de TIERRA, tú eliges los objetivos de los ataques de tu adversario. Si esta carta es mandada al Cementerio: puedes seleccionar 1 monstruo ' + MW + ' de Nivel 4 o menor en tu Cementerio, excepto "Magnet Warrior Sigma Plus"; añádelo a tu mano o Invócalo de Modo Especial.' + once("Magnet Warrior Sigma Plus"),
"Skilled Brown Magician": 'Cada vez que se active una Carta Mágica, pon 1 Contador de Magia en esta carta cuando esa Mágica se resuelva (máx. 3). Puedes quitar 1 Contador de Magia de esta carta y, después, activar 1 de estos efectos;\n● Esta carta gana 1500 ATK y su Nivel aumenta en 1.\n● Añade a tu mano 1 monstruo ' + KB + ' o 1 "Multiply" de tu Deck o Cementerio.\nSólo puedes usar este efecto de "Skilled Brown Magician" una vez por turno.',
"Kuribabylon": 'Gana 300 ATK/DEF por cada monstruo ' + KB + ' que controles y en tu Cementerio. Sólo puedes usar 1 de los siguientes efectos de "Kuribabylon" por turno, y sólo una vez ese turno.\n● Si tienes más monstruos en tu Cementerio que tu adversario: puedes Invocar esta carta de Modo Especial desde tu mano.\n● Durante tu Main Phase o Battle Phase: puedes devolver esta carta a la mano y, si lo haces, Invoca de Modo Especial 5 monstruos ' + FIVE + ' de tu mano y/o Cementerio en Posición de Ataque.',
"Winged Kuriboh LV6": '(Esta carta siempre se trata como una carta "Elemental HERO" y "Favorite".)\nNo puede ser Invocada de Modo Normal ni Colocada. Debe ser Invocada de Modo Especial (desde tu mano o Cementerio) desterrando 1 Monstruo de Fusión "Elemental HERO" o 1 "Winged Kuriboh" de tu mano, Campo boca arriba o Cementerio. Sólo puedes Invocar de Modo Especial "Winged Kuriboh LV6" una vez por turno de esta forma. Cuando un monstruo de tu adversario declare un ataque, o tu adversario active un efecto de monstruo en el Campo (Efecto Rápido): puedes Sacrificar esta carta; destruye ese monstruo y, si lo haces, inflige a tu adversario daño igual a su ATK original.',
"Conduction Warrior Linear Magnum Plus Minus": 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial (desde tu mano) mandando al Cementerio 2 monstruos ' + MW + ' con un Nivel original de 4 o menor de tu mano, Deck y/o Campo boca arriba. Sólo puedes Invocar de Modo Especial "Conduction Warrior Linear Magnum Plus Minus" una vez por turno de esta forma. Puedes seleccionar 1 otro monstruo de TIERRA en el Campo; esta carta gana la mitad del ATK de ese monstruo hasta el final de este turno. Si esta carta es destruida y mandada al Cementerio: añádela a tu mano.' + each("Conduction Warrior Linear Magnum Plus Minus"),
"Berserkion the Electromagna Warrior": 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial (desde tu mano) desterrando 1 "Alpha The Electromagnet Warrior", "Beta The Electromagnet Warrior" y "Gamma The Electromagnet Warrior" de tu mano, Cementerio y/o boca arriba de tu Zona de Monstruos. Puedes desterrar 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Cementerio y, después, seleccionar 1 carta que controle tu adversario; destrúyela. Si esta carta es destruida en batalla, o si esta carta en posesión de su dueño es destruida por un efecto de carta de tu adversario: puedes seleccionar 1 de cada uno de tus "Alpha The Electromagnet Warrior", "Beta The Electromagnet Warrior" y "Gamma The Electromagnet Warrior" desterrados; Invócalos de Modo Especial.',
"Plasma Warrior Eitom": '(Esta carta siempre se trata como una carta ' + MA + '.)\nNo puede ser Invocada de Modo Normal ni Colocada. Debe ser Invocada de Modo Especial (desde tu mano o Cementerio) Sacrificando 1 monstruo de Nivel 7 o mayor. Sólo puedes Invocar de Modo Especial "Plasma Warrior Eitom" una vez por turno de esta forma. Una vez por turno: puedes mandar al Cementerio 1 monstruo ' + MW + ' o ' + MA + ' de tu Deck, excepto "Plasma Warrior Eitom"; durante el resto de este turno, el ATK original de esta carta pasa a ser 1500 y, además, puede atacar directamente.',
"Tellusion the Magna Warrior": 'No puede ser Invocada de Modo Normal ni Colocada. Debe ser Invocada de Modo Especial (desde tu Cementerio) desterrando 1 "Magnet Warrior Sigma Plus" y 1 "Magnet Warrior Sigma Minus" de tu mano, Zona de Monstruos boca arriba y/o Cementerio. Una vez por turno, cuando tu adversario active una carta o efecto (Efecto Rápido): puedes seleccionar 1 monstruo que controle tu adversario; destrúyelo o, si seleccionaste un monstruo de TIERRA, puedes tomar su control en su lugar. Durante el turno de tu adversario (Efecto Rápido): puedes Sacrificar esta carta; Invoca de Modo Especial 2 de tus monstruos "Magnet Warrior Sigma" desterrados.',
"Winged Kuriboh LV9": 'Activa este efecto sólo como Eslabón de Cadena 3 o superior (Efecto Rápido): puedes Invocar esta carta de Modo Especial desde tu mano. Las Cartas Mágicas que han sido activadas son desterradas en lugar de ser mandadas al Cementerio. El ATK/DEF de esta carta es igual al número de Mágicas en el Cementerio de tu adversario x 500. Sólo puedes controlar 1 "Winged Kuriboh LV9".',
"Alluring Mirror Split": 'Cuando un "Harpie Lady" o "Harpie Lady Sisters" que controlas sea destruido en batalla: puedes Invocar de Modo Especial 1 monstruo ' + HP + ' de tu Deck con un nombre original distinto al del monstruo destruido. Si esta carta que controlas es destruida por el efecto de una carta ' + HP + ' o por un efecto de carta de tu adversario: selecciona 1 monstruo ' + HP + ' en tu Cementerio; Invócalo de Modo Especial.' + each("Alluring Mirror Split"),
"Detonate": 'Destruye tantos "Kuriboh" y "Kuriboh Tokens" que controles como sea posible y, después, destruye cartas que controle tu adversario, hasta el número de cartas destruidas por este efecto.',
"Five Star Twilight": 'Si el único monstruo que controlas es 1 monstruo de Nivel 5: Sacrifica ese monstruo; Invoca de Modo Especial 5 monstruos ' + FIVE + ' de tu mano, Deck y/o Cementerio, pero no pueden ser Sacrificados para una Invocación por Sacrificio. Sólo puedes activar 1 "Five Star Twilight" por turno.',
"Generation Next": 'Si tus LP son menores que los de tu adversario: añade a tu mano, o Invoca de Modo Especial, 1 monstruo "Elemental HERO", ' + KB + ' o "Neo-Spacian" de tu Deck o Cementerio, con ATK menor o igual que la diferencia de LP y, además, durante el resto de este turno, no puedes activar cartas, ni los efectos de cartas, con el mismo nombre que esa carta. Sólo puedes activar 1 "Generation Next" por turno.',
"Magnet Bonding": 'Durante la Main Phase: activa 1 de estos efectos (pero sólo puedes usar cada efecto de "Magnet Bonding" una vez por turno);\n● Añade a tu mano 1 "Conduction Warrior Linear Magnum Plus Minus" o 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Deck.\n● Añade a tu mano 1 monstruo ' + MA + ' de Nivel 8 de tu Deck.\n● Invoca por Fusión 1 Monstruo de Fusión de Tipo Roca de tu Extra Deck, barajando en el Deck como material monstruos de Tipo Roca de tu mano, Campo, Cementerio y/o desterrados.',
"Magnet Circle LV2": 'Invoca de Modo Especial 1 monstruo de Tipo Máquina de Nivel 2 o menor de tu mano.',
"Magnet Induction": 'Si controlas un monstruo ' + MW + ' cuyo Nivel original sea 4 o menor: Invoca de Modo Especial 1 monstruo ' + MW + ' de Nivel 4 o menor de tu Deck con un nombre distinto al de las cartas que controlas y, además, durante el resto de este turno después de que esta carta se resuelva, los monstruos ' + MW + ' y ' + MA + ' que controlas no pueden ser destruidos en batalla ni por efectos de cartas de tu adversario. Sólo puedes activar 1 "Magnet Induction" por turno.',
"Magnet Reverse": 'Selecciona 1 de tus monstruos de Tipo Máquina o Roca, que esté desterrado o en tu Cementerio, que no pueda ser Invocado de Modo Normal ni Colocado; Invócalo de Modo Especial.',
"Magnetic Field": 'Si controlas un monstruo de TIERRA de Tipo Roca de Nivel 4 o menor: puedes seleccionar 1 monstruo ' + MW + ' de Nivel 4 o menor en tu Cementerio; Invócalo de Modo Especial.' + once("Magnetic Field") + ' Una vez por turno, al final del Damage Step, cuando un monstruo de TIERRA de Tipo Roca que controlas combatió con un monstruo de tu adversario, pero el monstruo de tu adversario no fue destruido en la batalla: puedes devolver ese monstruo de tu adversario a la mano.',
"The Flute of Summoning Kuriboh": 'Toma 1 "Kuriboh" o 1 "Winged Kuriboh" de tu Deck, y añádelo a tu mano o Invócalo de Modo Especial.',
"Cyber Slash Harpie Lady": '1 Cantante + 1 o más monstruos que no sean Cantantes\nPara la Invocación por Sincronía de esta carta, puedes tratar como Cantante 1 monstruo ' + HP + ' que controles. El nombre de esta carta pasa a ser "Harpie Lady" mientras esté en el Campo o en el Cementerio. Cuando se active una Carta o efecto Mágico/de Trampa (excepto durante el Damage Step) (Efecto Rápido): puedes seleccionar 1 monstruo que controle tu adversario o 1 monstruo ' + HP + ' que controles; devuélvelo a la mano.' + once("Cyber Slash Harpie Lady"),
"Harpie Lady Elegance": 'Baraja en el Deck 1 "Harpie Lady Sisters" de tu Zona de Monstruos y, después, puedes Invocar de Modo Especial 3 monstruos ' + HP + ' con nombres originales distintos, 1 de cada uno: tu mano, Deck y Cementerio. Durante el resto de este turno después de que esta carta se resuelva, no puedes Invocar de Modo Especial monstruos, excepto monstruos de VIENTO. Si esta carta que controlas es destruida por el efecto de una carta ' + HP + ' o por un efecto de carta de tu adversario: añade a tu mano 1 monstruo ' + HP + ' de tu Deck.' + each("Harpie Lady Elegance"),
"Magnet Conversion": 'Selecciona hasta 3 monstruos ' + MW + ' de Nivel 4 o menor en tu Cementerio; añádelos a tu mano. Durante el turno de cualquier jugador, excepto el turno en que esta carta fue mandada al Cementerio: puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 de tus monstruos ' + MW + ' de Nivel 4 o menor desterrados; Invócalo de Modo Especial.',
"Magnet Force": 'Este turno, todos los monstruos en el Campo cuyos Tipos originales sean Máquina o Roca no son afectados por los efectos de monstruo de tu adversario (excepto los suyos propios).',
}
